/* BCMH cases — content from the IEYA study guide (Baruffwala 2026), BCMH master notes and the illness-scripts doc */
'use strict';

CASE({
  id: 'anaphylaxis', cat: ['BCMH', 'CVS'], covers: ['Anaphylaxis', 'Anaphylactic shock'], title: 'Anaphylaxis', dx: 'Anaphylaxis (anaphylactic / distributive shock)',
  syn: ['anaphylaxis', 'anaphylactic'], dxKw: ['anaphylax', 'urticaria|rash|angioedema|lip', 'wheeze|stridor|hoarse|airway', 'hypotension|shock|bp'],
  dxWhy: 'Rapid onset after a trigger with skin/mucosal involvement (urticaria, angioedema) plus airway (hoarse voice, stridor), breathing (wheeze, ↓SpO₂) or circulation (hypotension, tachycardia) compromise. It is a clinical diagnosis — don\'t wait for tests. Differentials: acute urticaria/angioedema alone, severe asthma, vasovagal collapse, ACE-inhibitor (bradykinin) angioedema (no urticaria).',
  susp: 'Anaphylaxis — a rapid-onset generalised type I (IgE-mediated) hypersensitivity reaction right after exposure to a likely trigger (drug, food or venom), especially in an atopic/asthmatic person or one with a previous reaction. Differentials: severe asthma, isolated urticaria/angioedema, vasovagal collapse.',
  suspKw: ['anaphyla', 'allerg|hypersensitivity|ige', 'trigger|food|drug|antibiotic|sting|venom|peanut', 'asthma|vasovagal|urticaria|angioedema'],
  avoid: ['penallergy'],
  gen: r => {
    const trig = r.w({drug: 3, food: 2, venom: 1});
    const child = trig === 'food' && r.chance(0.5);
    const sex = r.sex(0.55), age = child ? r.int(6, 15) : r.int(18, 62);
    const shock = r.chance(0.7);
    const onBB = !child && age > 45 && r.chance(0.4);
    const drug = r.pick(['IV amoxicillin-clavulanate', 'IV ceftriaxone', 'a diclofenac injection']);
    const food = r.pick(['peanut sauce', 'a prawn curry', 'a cake with nuts']);
    const late = !shock && r.chance(0.3);
    const pc = trig === 'drug' ? `"My throat… it's closing… I feel like I'm going to faint."` : trig === 'food' ? (child ? `"Mummy, I can't breathe properly… it's itchy everywhere."` : `"I ate something and now my lips are huge and I can't breathe."`) : `"A bee stung me in the garden, now I'm itching everywhere and I feel dizzy."`;
    return {
      sex, age, build: r.build(), setting: trig === 'drug' ? r.pick(['Medical ward, Helen Joseph Hospital', 'Short-stay ward, Charlotte Maxeke', 'Casualty, Tambo Memorial']) : r.hosp(child ? 'peds' : null),
      job: child ? 'learner' : r.pick(['teacher', 'student', 'security guard', 'chef', 'domestic worker', 'mechanic']),
      parentName: child ? 'His mother' : null,
      brief: trig === 'drug' ? `Admitted with pyelonephritis/cellulitis. ${drug} started ${r.int(3, 9)} minutes ago; nurse called because of a rash and breathing difficulty.` : trig === 'food' ? `Brought in ${late ? 'about 40 minutes' : '15 minutes'} after eating ${food} at a ${child ? 'birthday party' : 'restaurant'}. Itchy rash, swollen lips, wheeze.` : 'Stung by a bee 10 minutes ago. Generalised itch and dizziness.',
      pc,
      v: shock ? {hr: r.int(124, 142), sbp: r.int(68, 84), dbp: r.int(36, 48), rr: r.int(28, 34), sat: r.int(86, 91), t: 36.8, gcs: r.int(13, 15)} : {hr: r.int(108, 122), sbp: r.int(98, 112), dbp: r.int(58, 70), rr: r.int(24, 28), sat: r.int(91, 94), t: 36.7, gcs: 15},
      signs: ['urticaria', 'lipSwelling', 'distress', 'flushed'].concat(r.chance(0.5) ? ['wheeze'] : []),
      flags: {anaphylaxis: true, asthma: r.chance(0.5)},
      meds: onBB ? ['propranolol'] : [],
      prof: [[`${age} years old`, 0, 'Anaphylaxis occurs at any age (children: foods; adults: drugs, venom).'], [sex === 'F' ? 'Female' : 'Male', 0, 'Sex is not a major factor here.'], ['History of asthma / allergic rhinitis', 1, 'Atopy and asthma increase the risk of severe anaphylaxis and of death.'], [trig === 'drug' ? `Received ${drug} minutes ago` : trig === 'food' ? `Ate ${food} just before` : 'Bee sting minutes ago', 1, 'Temporal relationship to a known trigger (β-lactams/NSAIDs, foods like peanut, venom) is the key to diagnosis.'], ...(onBB ? [['Takes propranolol', 1, 'β-blockers blunt adrenaline\'s β effects → may be refractory → glucagon.']] : []), [r.pick(['Lives in Soweto', 'Lives in Benoni', 'From Tembisa']), 0, 'Not relevant.']],
      hx: [
        ['Timing / trigger', trig === 'drug' ? `They put the drip in and maybe five minutes later my skin started burning and itching.` : trig === 'food' ? `It started ${late ? 'half an hour' : 'a few minutes'} after we ate the ${food}.` : 'Straight after the sting — maybe two minutes.', 1, 'Rapid onset (minutes) after exposure.'],
        ['Breathing / throat', 'My throat feels tight and my voice sounds funny. I\'m wheezing.', 1, 'Hoarse voice/throat tightness = laryngeal oedema → airway threat.'],
        ['Skin', 'Itchy bumps all over, and my lips and eyes are swelling.', 1],
        ['Dizziness / collapse', shock ? 'I nearly fainted when I tried to stand up.' : 'A bit light-headed.', shock ? 1 : 0],
        ['Gut symptoms', trig !== 'drug' ? 'Cramps, I vomited once.' : 'No, not really.', 0],
        ['Previous reactions', r.chance(0.5) ? 'Once before I got a rash with something, but nothing like this.' : 'Never had this before.', 1, 'A previous reaction raises the risk; ask every time.'],
        ['Asthma / atopy', 'I have asthma and hay fever since childhood.', 1, 'Atopy/asthma = higher risk of severe or fatal anaphylaxis.'],
        ['Chest pain', r.chance(0.2) ? 'There\'s a tight pain in my chest.' : 'No chest pain.', 0, 'Chest pain/ST changes → Kounis syndrome (coronary vasospasm).'],
      ],
      ex: [['General (end of bed)', `Anxious, ${shock ? 'pale-flushed and clammy' : 'flushed'}. Widespread raised wheals (urticaria). Lip and periorbital swelling (angioedema). Hoarse voice.`, 1], ['Respiratory', 'Audible wheeze, prolonged expiration, bilateral polyphonic wheeze. ' + (r.chance(0.3) ? 'Soft inspiratory stridor.' : 'No stridor yet.'), 1], ['Cardiovascular', `Tachycardic, ${shock ? 'thready pulse, warm peripheries (distributive), capillary refill 3 s.' : 'pulse full.'} JVP not visible.`, 1], ['Skin', 'Generalised urticaria — blanching raised wheals with erythema, intensely itchy.', 1]],
      lab: {Lact: shock ? [3.2, 5.5] : [1.2, 2.0], Eos: [0.2, 0.6]},
      res: {PANEL_TROP: 'Not routinely needed unless chest pain (Kounis).', TRYP: null},
      cxr: {},
    };
  },
  keyInv: [], okInv: ['PANEL_FBC', 'PANEL_UE', 'ECG', 'PANEL_ABG', 'PANEL_LACT'],
  must: [{k: 'adrenaline_im', n: 'IM adrenaline 0.5 mg (1:1000) anterolateral thigh', why: 'First-line and life-saving: α1 vasoconstriction ↓ mucosal oedema and ↑ SVR, β1 ↑ HR/contractility, β2 bronchodilation + mast-cell stabilisation. Repeat after 5 min if no improvement.'},
    {k: 'o2', n: 'High-flow oxygen', why: 'Bronchospasm and laryngeal oedema → hypoxia.'},
    {k: 'fluid', n: 'IV crystalloid bolus (adult 500–1000 ml; child 10–20 ml/kg)', why: 'Capillary leak loses up to 35% of plasma volume within minutes — fill the "pipes that are too big".'}],
  good: {adrenaline_im: {m: 'Within minutes the wheeze eases, BP climbs and the wheals start to fade. (α1 + β1 + β2 effects.)', fx: {v: {sbp: +28, hr: -14, sat: +5, rr: -6}, unsign: ['distress', 'wheeze']}},
    fluid: {m: 'BP improving with volume — the leak has been partly replaced.', fx: {v: {sbp: +10, hr: -6}}},
    o2: {m: 'Saturation picking up on oxygen.', fx: {v: {sat: +4}}},
    salb_neb: {m: 'Residual wheeze settling with the nebuliser (adjunct for persistent bronchospasm).', fx: {v: {sat: +2, rr: -2}}}},
  bad: {chlorphen: {sev: 'warn', t: 'Adjunct only', m: 'H1 antihistamines help itch and urticaria only — they do not reverse airway oedema, bronchospasm or shock. Never delay adrenaline for them.', when: p => true}},
  crit: {after: 10, every: 10, fx: {sbp: -8, hr: +6, sat: -3, gcs: -1}, stop: ['adrenaline_im'], msg: 'Without adrenaline the vasodilation and capillary leak progressed — BP and saturation fell to peri-arrest levels. IM adrenaline is the first drug, given within minutes.'},
  Q: [
    {s: 'mech', q: 'Explain the immunological mechanism of this reaction, from first exposure to re-exposure.', a: 'Type I (IgE-mediated) hypersensitivity (Gell & Coombs). Sensitisation: first exposure → TH2 cells (IL-4, IL-13) → B cells class-switch to IgE → IgE binds FcεRI on mast cells and basophils ("armed"). Re-exposure: allergen cross-links bound IgE → degranulation: preformed histamine, tryptase, heparin; newly made leukotrienes C4/D4/E4 (bronchoconstriction), prostaglandin D2, PAF. Late phase (2–24 h): eosinophils and IL-5 → biphasic reaction. Anaphylactoid reactions look the same but bypass IgE (direct mast-cell activation: contrast, vancomycin, opioids, NSAIDs).', kw: ['type i|type 1|ige', 'mast cell|basophil', 'cross-link|crosslink|re-exposure|degranulat', 'histamine|leukotriene|tryptase', 'th2|il-4|class switch|sensitis']},
    {s: 'mech', q: 'Why is the patient hypotensive? Describe the haemodynamics of this type of shock.', a: 'Distributive shock ("pipes too big"): histamine, leukotrienes and NO cause arteriolar vasodilation → ↓SVR, and increased capillary permeability lets up to 35% of plasma volume leak out within minutes → ↓venous return → ↓preload → ↓stroke volume → ↓CO (MAP = CO × SVR). Early CO is normal/↑, SVR ↓↓, JVP low, skin warm and flushed (unlike hypovolaemic/cardiogenic shock); lactate rises as perfusion fails. Coronary vasospasm can cause ischaemia (Kounis syndrome).', kw: ['distributive|vasodilat', 'svr|resistance', 'capillary|leak|permeab', 'preload|venous return|cardiac output|map']},
    {s: 'comp', q: 'Why must this patient be observed for several hours after recovery? What else could go wrong?', a: 'Biphasic reaction: late-phase mediators (leukotrienes, eosinophils, IL-5) can cause recurrence 2–24 h later — observe ≥6–12 h. Other dangers: airway loss from laryngeal oedema (stridor, hoarse voice), silent chest, refractory shock, Kounis syndrome (chest pain/ST changes), cardiac arrest. Patients on β-blockers may be refractory to adrenaline.', kw: ['biphasic|late phase|recurr', '6|12|hours|observe', 'airway|laryng|stridor', 'arrest|refractory|kounis|beta']},
    {s: 'inv', q: 'Which blood test supports the diagnosis, when should it be taken, and what later tests identify the trigger?', a: 'Serum mast-cell tryptase 1–3 h after onset — released with histamine during degranulation and more stable; it confirms mast-cell degranulation. Total IgE does not correlate with an acute reaction. Later as an outpatient: specific IgE and skin-prick tests with positive (histamine) and negative (saline) controls — never skin-prick test during or soon after a reaction. Diagnosis is clinical — don\'t wait for tests to treat.', kw: ['tryptase', '1-3|1–3|1 to 3|hour', 'specific ige|skin prick|skin-prick', 'clinical']},
    {s: 'mgmt', q: 'Outline your immediate and discharge management.', a: 'ABCDE, call for help, remove the trigger (stop the infusion). IM adrenaline 1:1000 into the anterolateral thigh (adult 0.5 mg), repeat after 5 min if no improvement. Lie flat with legs raised (sit up if breathing worse; left lateral if pregnant). High-flow oxygen, IV crystalloid bolus (500–1000 ml adult; 10–20 ml/kg child), continuous monitoring. Adjuncts only after adrenaline: H1 antihistamine (itch/urticaria), hydrocortisone (may reduce late phase), nebulised salbutamol for persistent wheeze. Refractory after 2 IM doses → IV adrenaline infusion in a monitored setting/ICU; on β-blockers → glucagon. Discharge: observe ≥6–12 h, adrenaline auto-injector + teaching, allergy bracelet, written plan, allergist referral, record the allergy and report the ADR.', kw: ['adrenaline|epinephrine', 'im|intramuscular|thigh', 'oxygen|o2', 'fluid|crystalloid|bolus', 'repeat|5 min', 'auto-injector|epipen|bracelet|allerg|observe']},
    {s: 'pharm', q: 'How does adrenaline reverse each part of anaphylaxis? Why should it never be given as a 1:1000 IV bolus?', a: 'α1 → vasoconstriction (↑SVR, ↑BP) and ↓ mucosal oedema; β1 → ↑ heart rate and contractility; β2 → bronchodilation and mast-cell stabilisation (less mediator release). 1:1000 IV bolus in someone with a pulse causes severe hypertension and arrhythmias (VT/VF) — IV adrenaline is only given as a titrated infusion in a monitored setting (or 1 mg IV in cardiac arrest).', kw: ['alpha|α1|α', 'vasoconstrict', 'beta 1|β1|contractil|heart rate', 'beta 2|β2|bronchodilat', 'mast cell|stabilis', 'arrhythm|vt|vf|hypertens']},
    {s: 'pharm', q: 'If this patient were on propranolol, why might adrenaline fail, and what would you give?', a: 'β-blockers blunt adrenaline\'s β1/β2 effects (and leave unopposed α effects) → refractory anaphylaxis. Glucagon IV raises intracellular cAMP by bypassing β-receptors (positive inotropy/chronotropy). Noradrenaline/vasopressin are second-line vasopressors if refractory. Antihistamines and steroids do not treat shock.', kw: ['beta|β|block', 'glucagon', 'camp|cyclic amp|bypass']},
    {s: 'theme', q: 'What patient-safety and public-health actions follow this event?', a: 'Record the allergy prominently (wristband, folder) and ask before every drug; report the adverse drug reaction (pharmacovigilance); teach auto-injector use and avoidance (patient-centred self-management); written action plan and allergy bracelet. For transfusion anaphylaxis: stop the transfusion, keep the bag, report to the blood bank (haemovigilance). Theatre safety checklists and disclosure/documentation of the reaction.', kw: ['record|document|wristband|folder', 'report|pharmacovigilance|adr', 'auto-injector|epipen|educat|teach', 'bracelet|plan']},
  ],
  summary: 'Severe rapid-onset generalised type I (IgE) hypersensitivity: skin/mucosa + airway, breathing or circulation. Triggers: β-lactams, NSAIDs, contrast, NMBs, latex, peanut/shellfish, venom. Distributive shock: ↓SVR + capillary leak (up to 35% plasma volume), warm peripheries, low JVP. Tests: mast-cell tryptase 1–3 h (clinical diagnosis). Rx: IM adrenaline 1:1000 thigh (0.5 mg adult), repeat 5 min; O₂, fluids (500–1000 ml / 10–20 ml/kg), legs up; adjuncts antihistamine, hydrocortisone, salbutamol; refractory → adrenaline infusion; β-blocker → glucagon. Observe 6–12 h (biphasic). ACE-inhibitor angioedema is bradykinin-mediated (no urticaria).',
  src: 'IEYA study guide pp. 20–25; BCMH practice cluster "Collapse after an antibiotic"',
  real: [],
});

CASE({
  id: 'sle', cat: ['BCMH', 'Renal', 'Haem'], covers: ['Systemic lupus erythematosus', 'Lupus nephritis'], title: 'SLE with lupus nephritis', dx: 'Systemic lupus erythematosus with lupus nephritis',
  syn: ['lupus', 'sle'], dxKw: ['lupus|sle', 'malar|rash|photosens', 'arthritis|arthralgia|joint', 'nephritis|proteinuria|haematuria|kidney|renal'],
  dxWhy: 'Young woman with malar (butterfly) rash sparing the nasolabial folds, photosensitivity, painless oral ulcers, non-erosive arthritis and now frothy urine, oedema and hypertension with active urine sediment — a multisystem autoimmune picture ("SOAP BRAIN MD"). Differentials: post-streptococcal GN, rheumatoid arthritis, drug-induced lupus, HIV-associated nephropathy.',
  susp: 'A young woman with joint pains, rash and fatigue → think of a multisystem autoimmune disease, especially SLE (F:M ≈ 9:1, more common and severe in Black African women, important cause of glomerular disease in young SA women). Differentials: rheumatoid arthritis, viral arthritis, HIV.',
  suspKw: ['lupus|sle|autoimmune', 'young|woman|female', 'rash|joint|arthr', 'rheumatoid|hiv|viral'],
  avoid: ['pregnancy', 'ckd'],
  gen: r => {
    const age = r.int(17, 34), neph = r.w({nephritic: 2, nephrotic: 1});
    return {
      sex: 'F', age, build: r.build({thin: 1, normal: 3, overweight: 1}), eth: 'african', setting: r.pick(['Medical OPD, Chris Hani Baragwanath', 'Rheumatology clinic referral, Charlotte Maxeke', 'Emergency unit, Helen Joseph Hospital']), job: r.pick(['call-centre agent', 'nursing student', 'hairdresser', 'teacher']),
      noPreg: true,
      brief: `Referred from clinic: ${r.int(3, 8)} months of joint pains and tiredness, now swollen face and legs for 2 weeks. Urine dipstick at clinic: blood 3+, protein 3+.`,
      pc: '"My joints have been sore for months, and now my face and legs are swelling. My urine is foamy."',
      v: {hr: r.int(88, 104), sbp: r.int(150, 172), dbp: r.int(96, 108), rr: 18, sat: 98, t: r.f(37.4, 38.2), gcs: 15},
      signs: ['malar', 'oedema'],
      flags: {},
      prof: [['Female', 1, 'F:M ≈ 9:1 — oestrogen is a recognised factor.'], [`${age} years old`, 1, 'Child-bearing age (15–45) is the classic window.'], ['Black African woman', 1, 'SLE is more common and more severe in Black African patients, with a higher lupus nephritis rate.'], ['Works outdoors at weekends (market stall)', 1, 'UV light is a trigger (photosensitivity, flares).'], ['Uses hair relaxer', 0, 'Not relevant.']],
      hx: [
        ['Joints', 'My fingers, wrists and knees are sore and stiff in the morning, on and off for months. They don\'t look bent or damaged.', 1, 'Non-erosive arthritis (Jaccoud) — unlike RA.'],
        ['Rash', 'I get a red rash on my cheeks and nose when I\'m in the sun.', 1, 'Malar rash sparing nasolabial folds + photosensitivity.'],
        ['Mouth', 'Sometimes I get sores in my mouth but they don\'t hurt.', 1, 'Painless oral ulcers.'],
        ['Urine', 'It\'s been foamy, and maybe a bit dark. I\'m passing less.', 1, 'Proteinuria ± haematuria → lupus nephritis.'],
        ['Swelling', 'My eyes are puffy in the morning and my legs swell by evening.', 1],
        ['General', 'Tired all the time, I lost some weight, my hair is falling out more than usual, low fevers.', 1, 'Constitutional symptoms, alopecia.'],
        ['Cold fingers', 'My fingers go white then blue in the cold.', 0, 'Raynaud\'s.'],
        ['Chest pain', r.chance(0.4) ? 'A sharp pain when I breathe in, on the side.' : 'No.', 0, 'Serositis (pleuritis/pericarditis).'],
        ['Pregnancies', r.chance(0.4) ? 'I lost two pregnancies early.' : 'I have one child, the pregnancy was fine.', 0, 'Recurrent miscarriage → antiphospholipid syndrome.'],
        ['Medication', 'Only Panado and some ibuprofen from the pharmacy for the joints.', 0],
        ['HIV / TB', 'I tested negative last year.', 0],
      ],
      ex: [['Skin', 'Erythematous rash over cheeks and bridge of nose, sparing the nasolabial folds. Patchy non-scarring alopecia.', 1], ['Head & neck', 'Two painless ulcers on the hard palate. Periorbital puffiness.', 1], ['Musculoskeletal', 'Tender MCPs and wrists with soft-tissue swelling; no erosive deformity.', 1], ['Cardiovascular', 'BP raised. Pitting oedema to the knees. No rub.', 1], ['Abdomen', 'Soft. No organomegaly.', 0]],
      lab: {Hb: [9.2, 10.6], WCC: [2.6, 3.4], Lymph: [0.5, 0.9], Plt: [92, 140], ESR: [68, 105], CRP: [4, 9], Cr: neph === 'nephritic' ? [150, 240] : [95, 140], Urea: [9, 16], Alb: neph === 'nephrotic' ? [18, 24] : [26, 32], C3: [0.32, 0.6], C4: [0.04, 0.08], UPCR: neph === 'nephrotic' ? [360, 600] : [90, 250], Retic: [2.8, 4.5], LDH: [290, 420], Hapt: [0.05, 0.2], TBil: [22, 34]},
      res: {DIP: `Blood 3+ · Protein ${neph === 'nephrotic' ? '4+' : '3+'} · Leukocytes trace · Nitrites neg · Glucose neg · SG 1.020. Microscopy: dysmorphic RBCs and red cell casts.`, SERO: 'ANA positive (homogeneous, titre 1:1280). Anti-dsDNA 412 IU/mL (high). Anti-Smith positive. Anti-histone negative. RF negative. Anti-CCP negative. Direct Coombs positive.', BX: {text: `Renal biopsy: diffuse proliferative lupus nephritis (ISN/RPS class IV) with "wire-loop" capillary walls; full-house immune deposits on immunofluorescence.`, img: 'lupus_nephritis', cap: 'Lupus nephritis: normal vs focal vs diffuse proliferative'}, HIVR: 'Non-reactive.', USKUB: 'Kidneys normal-sized (11.2 and 11.5 cm), increased echogenicity. No hydronephrosis.'},
      cxr: r.chance(0.4) ? {effusion: {side: r.side(), size: 'small'}} : {},
    };
  },
  keyInv: ['DIP', 'SERO', 'PANEL_COMP', 'PANEL_UE', 'PANEL_FBC', 'PANEL_UPCR'], okInv: ['BX', 'PANEL_HAEMOL', 'PANEL_ESR', 'HIVR', 'USKUB', 'PANEL_LFT'],
  must: [{k: 'hcq', n: 'Hydroxychloroquine', why: 'For all SLE patients — reduces flares (annual eye check for retinopathy).'}, {k: 'steroid_sys', n: 'Corticosteroids for the flare', why: 'Organ-threatening flare (nephritis) needs corticosteroids.'}, {k: 'immunosupp|cyclophos', n: 'Immunosuppressant (mycophenolate / cyclophosphamide / azathioprine)', why: 'Organ involvement (lupus nephritis) needs immunosuppression, with urgent nephrology/biopsy.'}],
  good: {hcq: {m: 'Hydroxychloroquine started — reduces flares long-term.'}, prednisone: {m: 'Steroids started for the active flare.'}, methylpred: {m: 'Pulse methylprednisolone for organ-threatening lupus.'}},
  bad: {nsaid: {sev: 'harm', t: 'NSAID with active lupus nephritis', m: 'NSAIDs help lupus joint pain, but with active nephritis and a rising creatinine they reduce afferent prostaglandin vasodilation → GFR falls further. Avoid them now.', fx: {lab: {Cr: +40}}}},
  Q: [
    {s: 'cause', q: 'What factors predispose to SLE?', a: 'Genetic: HLA-DR2/3, complement C1q/C2/C4 deficiency. Hormonal: oestrogen (F:M ≈ 9:1, child-bearing age). Environmental: UV light, drugs (hydralazine, procainamide, isoniazid → drug-induced lupus), EBV. More common/severe in Black African patients.', kw: ['hla|genetic', 'complement|c1q|c4', 'oestrogen|estrogen|female', 'uv|sun|drug|ebv']},
    {s: 'mech', q: 'Explain the immunopathogenesis of SLE and how it damages the kidney and blood.', a: 'Defective clearance of apoptotic cells → nuclear antigens exposed → loss of self-tolerance → anti-nuclear antibodies. Type III hypersensitivity: antigen–antibody complexes deposit in glomeruli, skin, joints, serosa → complement activation (C3, C4 consumed) → neutrophils → inflammation (fibrinoid necrosis of vessels); in the kidney → lupus nephritis (wire-loop lesions). Type II: autoantibodies against cell surfaces → autoimmune haemolytic anaemia (Coombs+), thrombocytopenia, leucopenia.', kw: ['apoptotic|clearance|tolerance', 'antinuclear|ana|autoantibod', 'type iii|immune complex', 'complement|c3|c4', 'type ii|haemoly|coombs|cytopen']},
    {s: 'path', q: 'Name characteristic pathological findings of SLE.', a: 'Wire-loop lesions (lupus nephritis — class IV diffuse proliferative is worst), Libman–Sacks non-infective vegetations (both sides of the mitral valve), LE cells, onion-skin splenic arterioles, fibrinoid necrosis of vessels.', kw: ['wire loop|wire-loop', 'libman|sacks', 'onion|le cell|fibrinoid']},
    {s: 'comp', q: 'What complications does this patient risk?', a: 'Lupus nephritis → AKI/CKD (class IV worst), hypertension; cytopenias (haemolysis, thrombocytopenia → bleeding); serositis (pericarditis, pleuritis); neuropsychiatric lupus (seizures, psychosis); secondary antiphospholipid syndrome (arterial/venous thrombosis, PE, recurrent miscarriage); Libman–Sacks endocarditis; infection on immunosuppressants (fever = infection until proven otherwise); hydroxychloroquine retinopathy; pregnancy complications (flares, APS, neonatal lupus/congenital heart block with anti-Ro).', kw: ['renal|kidney|nephritis|aki|ckd', 'antiphospholipid|thromb|miscarr', 'seizure|psychosis|neuro', 'infection|pericard|pleur|serositis|cytopen']},
    {s: 'inv', q: 'Interpret the serology and urine. Which test screens, which is specific, and what tracks activity?', a: 'ANA is the screening test — positive in ~100% (sensitive, not specific; negative ANA ≈ rules out SLE). Anti-dsDNA is highly specific and its titre tracks disease activity and lupus nephritis. Anti-Smith is the most specific but insensitive. Low C3/C4 = complement consumption in active disease. ESR ↑ with normal CRP is the classic SLE pattern (CRP rises with infection/serositis). Anti-histone = drug-induced lupus. Urine: blood + protein with red cell casts = active glomerulonephritis → UPCR and renal biopsy (class I–VI).', kw: ['ana|antinuclear', 'sensitive|screen', 'dsdna|double', 'specific|activity', 'c3|c4|complement', 'esr|crp', 'cast|biopsy|protein']},
    {s: 'mgmt', q: 'How would you manage her?', a: 'Urgent nephrology referral and renal biopsy (rising creatinine, active sediment). Hydroxychloroquine for all (↓ flares; annual eye check). Corticosteroids for the flare; immunosuppressants for organ involvement (mycophenolate, cyclophosphamide, azathioprine). NSAIDs only for joints when kidneys are not involved. BP control and proteinuria reduction; sun protection. Pregnancy counselling, adherence, mental health support, shared decision-making about toxic drugs. Treat fever as infection until proven otherwise.', kw: ['hydroxychloroquine', 'steroid|prednis|methylpred', 'mycophenolate|cyclophosph|azathioprine|immunosupp', 'biopsy|nephrolog|refer', 'sun|bp|counsel']},
    {s: 'pharm', q: 'What important toxicity must be monitored with hydroxychloroquine, and what serious risk comes with immunosuppressants?', a: 'Hydroxychloroquine → retinopathy (annual eye check). Immunosuppressants/steroids → infection (fever in SLE on immunosuppressants = infection until proven otherwise; CRP rise helps distinguish), plus cyclophosphamide toxicity (marrow suppression, infertility, haemorrhagic cystitis) — shared decision-making.', kw: ['retin|eye', 'infection|immunosupp']},
  ],
  summary: 'Multisystem autoimmune disease: defective apoptotic clearance → ANA → type III immune complexes (C3/C4 consumed) ± type II cytopenias. Young women (F:M 9:1), worse in Black Africans. "SOAP BRAIN MD": serositis, oral ulcers, arthritis (non-erosive), photosensitivity, blood, renal, ANA, immunological (dsDNA/Sm/APL), neuro, malar rash, discoid. ANA = screen (sensitive), anti-dsDNA = specific + activity, anti-Sm most specific, anti-histone = drug-induced. ESR ↑ CRP normal. Lupus nephritis: biopsy, class IV diffuse proliferative worst, wire loops. Rx: hydroxychloroquine all, steroids for flares, mycophenolate/cyclophosphamide/azathioprine for organs, sun protection.',
  src: 'IEYA study guide pp. 26–28', real: ['sle_ana|ANA immunofluorescence patterns', 'lupus_nephritis|Lupus nephritis: normal, focal and diffuse proliferative'],
});

CASE({
  id: 'hiv_crypto', cat: ['BCMH'], covers: ['HIV/AIDS', 'Cryptococcal meningitis', 'Opportunistic infections'], title: 'Advanced HIV with an opportunistic infection', dx: 'Advanced HIV (AIDS) with cryptococcal meningitis',
  syn: ['cryptococcal', 'crypto', 'aids', 'advanced hiv'], dxKw: ['hiv|aids', 'crypto|meningitis', 'cd4|advanced|immunosupp', 'tb meningitis|bacterial|differential'],
  dxWhy: 'Weight loss, oral thrush (WHO stage 3) and a subacute severe headache with neck stiffness in someone untested/defaulted for HIV → CD4 almost certainly < 100 → cryptococcal meningitis is the leading cause. Differentials: TB meningitis, bacterial meningitis, toxoplasmosis (focal signs), CNS lymphoma.',
  susp: 'Advanced HIV disease (weight loss, oral thrush, recurrent infections) presenting with an opportunistic CNS infection — cryptococcal meningitis (CD4 < 100) vs TB meningitis vs bacterial meningitis vs toxoplasmosis.',
  suspKw: ['hiv|aids', 'opportunis|crypto|tb|meningitis', 'cd4|immunosupp|advanced'],
  avoid: ['hiv'], noOverlay: false,
  gen: r => {
    const sex = r.sex(0.45), age = r.int(24, 44);
    const known = r.chance(0.55);
    return {
      sex, age, build: r.build({cachectic: 3, thin: 3, normal: 1}), setting: r.hosp(), job: r.pick(['unemployed', 'taxi rank marshal', 'domestic worker', 'construction worker', 'hairdresser']),
      brief: `${r.int(2, 4)} weeks of worsening headache, now vomiting and confused at times. Weight loss. ${known ? 'Known HIV+, defaulted ART.' : 'Never tested for HIV.'}`,
      pc: '"My head is splitting, doctor, for weeks now. The light hurts my eyes. I keep vomiting."',
      v: {hr: r.int(96, 112), sbp: r.int(104, 122), dbp: r.int(64, 76), rr: 20, sat: 97, t: r.f(37.8, 38.6), gcs: r.int(13, 15)},
      signs: ['cachectic', 'pain', 'fever'],
      flags: {hiv: true, activeInfection: true},
      lab: {CD4: [12, 68], VL: [180000, 900000], Hb: [9.1, 10.8], Lymph: [0.3, 0.7], Na: [129, 134], Plt: [130, 190]},
      prof: [[`${age} years old`, 1, 'Adults 15–49 carry the HIV burden; SA ≈ 7.8 million PLWH (~13%).'], [sex === 'F' ? 'Young woman' : 'Young man', sex === 'F' ? 1 : 0, sex === 'F' ? 'Young women (15–24) have the highest incidence.' : 'Both sexes affected.'], [known ? 'Known HIV, stopped ART' : 'Never tested for HIV', 1, 'Untreated/defaulted HIV → falling CD4 → OIs by CD4 level.'], ['Lost 8 kg in 3 months', 1, 'Constitutional symptoms of advanced HIV (or TB).'], [r.pick(['Lives in Hillbrow', 'Lives in an informal settlement in Diepsloot']), 0, 'Context, not diagnostic.']],
      hx: [
        ['Headache', 'It started slowly 3 weeks ago and gets worse every day. It\'s all over my head. Lying down is worse.', 1, 'Subacute headache (raised ICP) — crypto/TB meningitis rather than bacterial.'],
        ['Vomiting / vision', 'I vomit in the mornings. Sometimes I see double.', 1, 'Raised intracranial pressure (6th nerve palsy).'],
        ['Fever / sweats', 'Fevers at night and I sweat.', 1],
        ['HIV status', known ? 'I was diagnosed in 2019. I took the pills for a while, then stopped last year — I was feeling fine and the clinic was far.' : 'I\'ve never tested. I was scared.', 1, 'Defaulting/never on ART.'],
        ['Mouth / swallowing', 'My mouth is full of white stuff, and swallowing hurts.', 1, 'Oral candida (stage 3); odynophagia suggests oesophageal candidiasis (stage 4).'],
        ['Weight', 'My clothes are hanging off me.', 1],
        ['Cough', r.chance(0.4) ? 'A cough for two weeks.' : 'No cough.', 0, 'Always screen for TB — leading cause of death in PLWH.'],
        ['Seizures / weakness', 'No fits. No weakness on one side.', 0, 'Focal signs/seizures → think toxoplasmosis or lymphoma.'],
        ['Confusion (from family)', 'My sister says I\'m repeating myself and forgetting things.', 1],
      ],
      ex: [['General (end of bed)', 'Wasted, photophobic, lying with eyes shut. Oral thrush.', 1], ['Head & neck', 'White plaques on tongue and palate that scrape off leaving a red bleeding base. Generalised lymphadenopathy.', 1], ['Neurological', `GCS ${'14'}/15, neck stiffness, Kernig positive. ${r.chance(0.5) ? 'Left 6th nerve palsy.' : 'Cranial nerves intact.'} No focal limb weakness. Fundi: papilloedema.`, 1], ['Skin', 'Papular pruritic eruption on the arms.', 0]],
      res: {HIVR: 'Reactive. Confirmatory rapid test: reactive.', CRAG: 'POSITIVE (serum CrAg lateral flow assay).', LP: {text: 'Opening pressure 34 cmH₂O (raised). CSF clear. WCC 18/µL (lymphocytes). Protein 0.9 g/L. Glucose 1.9 mmol/L (serum 5.4). India ink: encapsulated budding yeasts. CSF CrAg positive. Gram stain: no bacteria. GeneXpert CSF: MTB not detected.', img: 'cryptococcus', cap: 'India-ink stain: Cryptococcus neoformans with halo capsules'}, CTH: 'No space-occupying lesion, no hydrocephalus. (CT before LP if focal signs/↓GCS.)', SPXP: 'MTB not detected.', CXR: null},
      cxr: r.chance(0.3) ? {hilar: true} : {},
    };
  },
  keyInv: ['HIVR', 'PANEL_CD4', 'CRAG', 'LP'], okInv: ['CTH', 'PANEL_FBC', 'PANEL_UE', 'PANEL_VL', 'SPXP', 'CXR', 'PANEL_LFT', 'GLUCO'],
  must: [{k: 'ampho', n: 'Amphotericin B (induction, with flucytosine/fluconazole per guideline)', why: 'Cryptococcal meningitis needs induction antifungal therapy; amphotericin B for severe systemic disease (nephrotoxic, ↓K⁺/Mg²⁺ — monitor).'}, {k: 'fluco', n: 'Fluconazole (combination/consolidation)', why: 'Azole: inhibits lanosterol 14α-demethylase (CYP51) → ↓ ergosterol. Also used for CrAg-positive pre-emptive therapy and oral/oesophageal candida.'}],
  good: {ampho: {m: 'Induction antifungal started. Monitor K⁺, Mg²⁺ and creatinine (amphotericin is nephrotoxic).'}, fluco: {m: 'Fluconazole added.'}},
  bad: {tld: {sev: 'harm', t: 'ART started too early in cryptococcal meningitis', m: 'Starting ART immediately in cryptococcal (or TB) meningitis increases death from IRIS — delay ART 4–6 weeks after starting antifungal therapy.'}, efv: {sev: 'harm', t: 'ART started too early in cryptococcal meningitis', m: 'Delay ART 4–6 weeks in cryptococcal meningitis (IRIS risk).'}},
  Q: [
    {s: 'micro', q: 'Describe the structure of HIV and its life cycle, linking each step to a drug class.', a: 'Retroviridae, Lentivirus: enveloped, 2 copies of +ssRNA, conical p24 capsid, gp120 (binds CD4) + gp41 (fusion); co-receptors CCR5 (early, macrophage-tropic) / CXCR4 (CCR5Δ32 homozygotes resistant). Life cycle = drug targets: attach/fuse (enfuvirtide, maraviroc) → reverse transcriptase RNA→DNA (NRTI/NNRTI) → integrase inserts provirus (dolutegravir) → transcription → protease cleaves polyproteins (PIs) → budding; capsid inhibitor lenacapavir. RT is error-prone (no proof-reading) → huge diversity → resistance with poor adherence.', kw: ['rna|retrovir', 'gp120|cd4', 'reverse transcriptase|nrti|nnrti', 'integrase|dolutegravir', 'protease', 'ccr5|cxcr4|gp41|fusion']},
    {s: 'mech', q: 'Why does falling CD4 cause this kind of infection? Which OIs appear at which CD4 count?', a: 'CD4 loss → failure of TH1 help → ↓ cell-mediated immunity → intracellular pathogens (TB, PJP, Cryptococcus, Toxoplasma, CMV); chronic immune activation and gut CD4 depletion. By CD4: < 500 TB, herpes zoster, oral candida, Kaposi; < 200 PJP, oesophageal candida; < 100 Toxoplasma, cryptococcal meningitis; < 50 CMV retinitis, MAC.', kw: ['th1|cell-mediated|cell mediated', '500|tb', '200|pjp|pcp', '100|crypto|toxo', '50|cmv|mac']},
    {s: 'comp', q: 'What are the complications of cryptococcal meningitis and of starting ART?', a: 'Raised intracranial pressure (headache, vomiting, 6th nerve palsy, papilloedema, visual loss, ↓GCS) — needs therapeutic LPs; death. After ART: IRIS — paradoxical worsening of an OI as immunity recovers; to reduce it, start ART 4–6 weeks after antifungal therapy in crypto/TB meningitis (2 weeks after TB treatment otherwise). Amphotericin toxicity: nephrotoxicity, ↓K⁺, ↓Mg²⁺.', kw: ['intracranial|icp|pressure', 'iris|immune reconstitution', '4-6|4–6|weeks|delay', 'nephrotox|potassium|magnesium|blind|vision']},
    {s: 'inv', q: 'How do you diagnose HIV in an adult versus an infant, and how is treatment monitored? Interpret this CSF.', a: '< 18 months: HIV DNA PCR (maternal IgG crosses the placenta → antibody tests falsely +). ≥ 18 months: rapid test → confirmatory rapid/4th-gen ELISA (p24 Ag + Ab), window 2–4 weeks; with pre/post-test counselling and consent. Monitoring: viral load (best adherence/treatment-response marker; suppressed < 50), CD4 (immune status, prophylaxis), safety bloods (Hb for AZT, creatinine for TDF). Virological failure: VL > 1000 ×2 despite adherence support. CSF: raised opening pressure, lymphocytic, high protein, low glucose with India-ink yeasts and CrAg+ = cryptococcal meningitis (CrAg screen if CD4 < 100).', kw: ['pcr|dna|18 months', 'rapid|elisa|antibod|4th', 'viral load', 'cd4', 'crag|india ink|yeast|crypto', 'pressure|lymphocyt|glucose|protein']},
    {s: 'mgmt', q: 'Outline the management of this patient, including HIV care.', a: 'Admit. Induction antifungal therapy (amphotericin B-based, then fluconazole consolidation/maintenance); therapeutic LPs for raised pressure; monitor K⁺, Mg²⁺, creatinine. Delay ART 4–6 weeks (IRIS), then start TLD (TDF + 3TC + DTG). Co-trimoxazole prophylaxis (CD4 < 200: PJP, toxo); screen for TB (symptoms, Xpert); TB preventive therapy when TB excluded; treat oral/oesophageal candida (fluconazole). Adherence counselling, disclosure support, differentiated care once stable.', kw: ['amphotericin|antifungal|fluconazole', 'lp|lumbar|pressure', 'delay|4-6|weeks|iris', 'tld|art|dolutegravir', 'cotrimoxazole|prophylaxis', 'tb|adherence|counsel']},
    {s: 'pharm', q: 'Name SA first-line ART and give one key adverse effect of each component. What interaction appears in almost every past paper?', a: 'TLD = tenofovir DF (NtRTI) + lamivudine (NRTI) + dolutegravir (INSTI); children < 10: ABC + 3TC + DTG. TDF → renal tubular toxicity (Fanconi), ↓ bone density; DTG → insomnia, weight gain, ↑ creatinine (blocks secretion, not true ↓GFR), neural-tube concern (now reassured); EFV → vivid dreams/neuropsychiatric; AZT → anaemia; NVP → rash/hepatitis; ABC → hypersensitivity (HLA-B*5701). Rifampicin induces CYP3A4/UGT1A1 → ↓ DTG → give DTG twice daily.', kw: ['tenofovir', 'lamivudine', 'dolutegravir', 'renal|kidney|fanconi|bone', 'rifampicin', 'twice|double']},
    {s: 'theme', q: 'He asks you not to tell his partner. What are the ethical and legal principles?', a: 'Confidentiality: disclose to a partner only with consent — encourage patient-led disclosure. The doctor may disclose only if the patient refuses after counselling and the partner is at serious risk. Informed consent for testing with pre/post-test counselling; children ≥ 12 can consent to HIV testing (Children\'s Act). Address stigma; U=U; adherence counselling (viral load best adherence measure); 95-95-95 targets and differentiated service delivery.', kw: ['confidential', 'consent', 'disclos', 'counsel', 'serious risk|refuse|partner']},
  ],
  summary: 'HIV: lentivirus, gp120–CD4 (CCR5/CXCR4), RT error-prone. Acute → latency (PGL) → AIDS (CD4 < 200 or stage 4). OIs by CD4: < 500 TB/zoster/oral candida/KS; < 200 PJP/oesophageal candida; < 100 toxo/crypto; < 50 CMV/MAC. Dx: < 18 mo DNA PCR; ≥ 18 mo rapid + confirmatory/4th-gen. Monitor VL (< 50), CD4, creatinine/Hb. TLD first line; rifampicin → DTG bd. CTX prophylaxis CD4 < 200; CrAg screen CD4 < 100; TPT. IRIS: ART 2 wk after TB Rx, 4–6 wk in TB/crypto meningitis. Ethics: consent, confidentiality, partner disclosure, Children\'s Act ≥ 12.',
  src: 'IEYA study guide pp. 29–31; BCMH practice clusters', real: ['cryptococcus|India-ink: Cryptococcus', 'oral_candida|Oral thrush and cutaneous candidiasis'],
});

CASE({
  id: 'kaposi', cat: ['BCMH', 'Haem'], covers: ['Kaposi sarcoma'], title: 'Kaposi sarcoma', dx: 'Epidemic (AIDS-associated) Kaposi sarcoma',
  syn: ['kaposi', 'ks'], dxKw: ['kaposi', 'hhv|herpes', 'hiv|aids', 'bacillary|differential|melanoma|haemangioma'],
  dxWhy: 'Purple/red-brown non-blanching macules, plaques and nodules on the legs, face (tip of nose) and hard palate, with leg lymphoedema, in a person with untreated HIV = epidemic KS (WHO stage 4). Differentials: bacillary angiomatosis (Bartonella), pyogenic granuloma, haemangioma, melanoma.',
  susp: 'Purple skin/palate lesions in someone at risk of HIV → Kaposi sarcoma (HHV-8) until proven otherwise; differentials bacillary angiomatosis, haemangioma, melanoma, pyogenic granuloma.',
  suspKw: ['kaposi', 'hiv', 'hhv|herpes', 'bacillary|melanoma|haemangioma'],
  avoid: ['hiv'],
  gen: r => {
    const sex = r.sex(0.4), age = r.int(26, 45), visceral = r.chance(0.5), delay = r.int(3, 10);
    return {
      sex, age, build: r.build({cachectic: 1, thin: 2, normal: 2}), setting: r.pick(CLINICS), job: r.pick(['waiter', 'cashier', 'driver', 'street vendor']),
      brief: `Purple lumps on the legs for ${delay} months, slowly spreading. ${visceral ? 'Now coughing with blood-streaked sputum.' : 'Legs swollen.'}`,
      pc: `"These dark spots started on my legs ${delay} months ago. I thought they were bruises, but they're growing and now my legs are swelling."`,
      v: {hr: r.int(84, 100), sbp: 116, dbp: 72, rr: visceral ? 24 : 16, sat: visceral ? r.int(90, 94) : 98, t: 37.2, gcs: 15},
      signs: ['ks', 'oedema'].concat(visceral ? ['cough'] : []),
      flags: {hiv: true, ks: true},
      lab: {CD4: [70, 260], VL: [40000, 400000], Hb: [9.4, 11.2]},
      prof: [[`${age} years old`, 1, 'Epidemic KS affects young HIV+ adults.'], [sex === 'M' ? 'Male' : 'Female', sex === 'M' ? 1 : 0, 'Epidemic KS: M > F.'], ['HIV status unknown — never tested', 1, 'KS in SA is overwhelmingly HIV-associated; an AIDS-defining (stage 4) malignancy.'], [`Lesions present for ${delay} months before coming in`, 1, 'Delayed presentation — lesions progress patch → plaque → nodule.'], ['Lives with a partner', 0, 'Ask about partner testing/disclosure later.']],
      hx: [
        ['Skin lesions', 'They started flat like a bruise, then became raised and now some are lumps. They don\'t hurt or itch.', 1, 'Patch → plaque → nodule.'],
        ['Mouth', 'There\'s a purple patch on the roof of my mouth.', 1, 'Look in the mouth — hard palate involvement.'],
        ['Legs swelling', 'Both legs are swollen and tight, especially the left.', 1, 'Lymphoedema from lymphatic involvement.'],
        ['Breathing / cough', visceral ? 'I cough up blood-streaked spit and I get short of breath walking.' : 'No cough.', visceral ? 1 : 0, 'Pulmonary KS — differential of TB/PJP in HIV.'],
        ['Stool', r.chance(0.3) ? 'Sometimes my stool is black.' : 'Normal.', 0, 'GIT KS → bleeding.'],
        ['HIV', 'I\'ve never tested.', 1],
        ['Weight / sweats', 'I lost weight, some night sweats.', 0],
      ],
      ex: [['Skin', 'Multiple violaceous non-blanching macules, plaques and nodules on both shins and feet, one on the tip of the nose. Firm non-pitting lymphoedema of the legs.', 1], ['Head & neck', 'Violaceous plaque on the hard palate. Generalised lymphadenopathy.', 1], ['Respiratory', visceral ? 'Scattered crackles both bases.' : 'Clear.', visceral ? 1 : 0]],
      res: {HIVR: 'Reactive. Confirmatory test reactive.', BX: {text: 'Punch biopsy: spindle-cell proliferation forming slit-like vascular spaces with extravasated RBCs and haemosiderin. Immunohistochemistry: HHV-8 LANA-1 nuclear positivity; CD31, CD34 positive. Diagnosis: Kaposi sarcoma.', img: 'ks_skin', cap: 'Kaposi sarcoma: skin and palate lesions; spindle-cell histology'}, SPXP: 'MTB not detected.'},
      cxr: visceral ? {nodules: 5, effusion: {side: r.side(), size: 'small'}} : {},
    };
  },
  keyInv: ['HIVR', 'BX', 'PANEL_CD4'], okInv: ['PANEL_VL', 'CXR', 'SPXP', 'PANEL_FBC', 'PANEL_UE', 'PANEL_LFT', 'OGD', 'CRAG'],
  must: [{k: 'arv', n: 'ART (TLD)', why: 'Immune reconstitution is the most important step — 50–80% of mucocutaneous KS regresses with ART alone.'}, {k: 'chemo|anthracycline', n: 'Chemotherapy for visceral/extensive disease (liposomal doxorubicin / paclitaxel)', why: 'Visceral (pulmonary/GIT) or extensive KS needs systemic chemo with ART.'}],
  good: {tld: {m: 'ART started — immune reconstitution is the cornerstone of KS treatment. Warn about KS-IRIS (lesions may flare).'}, doxorub: {m: 'Doxorubicin for systemic disease.'}, paclitax: {m: 'Paclitaxel — second-line/alternative systemic therapy.'}},
  Q: [
    {s: 'micro', q: 'What virus causes this, and how does it cause cancer?', a: 'Human herpesvirus 8 (KSHV) — gamma-herpesvirus, dsDNA, latent in spindle (endothelial/lymphatic) cells; spread by saliva (main), sex, blood, organ transplant. LANA (latency-associated nuclear antigen) binds and inactivates p53 and pRb; viral cyclin D, vIL-6, vGPCR (and v-FLIP via NF-κB) → angiogenesis (VEGF), spindle-cell proliferation and blocked apoptosis. HIV-1 Tat protein stimulates spindle-cell proliferation and HHV-8 reactivation. HHV-8 also causes primary effusion lymphoma and multicentric Castleman disease.', kw: ['hhv-8|hhv8|herpesvirus 8|kshv', 'lana', 'p53', 'rb|prb', 'vegf|angiogen|cyclin|spindle', 'tat|saliva']},
    {s: 'path', q: 'Describe the forms, gross stages and histology of Kaposi sarcoma.', a: 'Four forms: classic (elderly Mediterranean/Eastern European/Ashkenazi men, legs, indolent), endemic African (children — lymphadenopathic, aggressive), iatrogenic/transplant, epidemic (AIDS) — most aggressive, widespread. Gross: patch → plaque → nodule (violaceous). Histology: spindle cells forming slit-like vascular spaces with extravasated RBCs and haemosiderin; IHC LANA-1/HHV-8 positive (diagnostic).', kw: ['classic|endemic|iatrogenic|epidemic', 'patch|plaque|nodule', 'spindle', 'slit', 'haemosiderin|extravasated|lana']},
    {s: 'comp', q: 'What complications can visceral KS cause, and what happens after starting ART?', a: 'Visceral involvement can occur without skin lesions: GIT (most common) → GI haemorrhage, obstruction; lung (most commonly fatal) → dyspnoea, haemoptysis, bloody effusion, nodular/reticular CXR infiltrates (differential TB/PJP); severe obstructive lymphoedema. KS-IRIS can flare after ART start; corticosteroids are contraindicated in KS-IRIS (can trigger explosive progression).', kw: ['gi|gut|bleed|haemorrh', 'lung|pulmonary|haemoptysis', 'lymphoedema', 'iris', 'steroid']},
    {s: 'inv', q: 'How is KS diagnosed, and what work-up follows?', a: 'Tissue biopsy (punch/excisional) with histology is the gold standard, confirmed by immunohistochemistry (HHV-8 LANA-1 nuclear staining, CD31, CD34). Work-up: HIV serology, CD4, viral load, FBC, U&E, LFTs, faecal occult blood; CXR or CT chest for pulmonary involvement; bronchoscopy or endoscopy if symptomatic.', kw: ['biopsy', 'histolog|immunohisto|lana', 'cd4|hiv|viral load', 'cxr|ct|endoscop|bronchoscop']},
    {s: 'mgmt', q: 'How is KS treated?', a: 'ART first — immune reconstitution regresses many lesions (50–80% of mucocutaneous KS). Systemic chemotherapy for extensive/visceral disease: liposomal doxorubicin or paclitaxel (second line bleomycin + vincristine). Local radiotherapy for symptomatic lesions. Avoid glucocorticoids. Screen for TB and other OIs, co-trimoxazole prophylaxis per CD4.', kw: ['art|antiretroviral|tld', 'doxorubicin|paclitaxel|chemo', 'radiotherap', 'steroid|avoid']},
    {s: 'pharm', q: 'Why are corticosteroids dangerous in KS?', a: 'Glucocorticoids can trigger explosive KS progression — avoid whenever possible, and they are contraindicated in KS-IRIS even though steroids are used for IRIS generally.', kw: ['progress|explosive|worsen', 'iris']},
  ],
  summary: 'HHV-8 vascular tumour (LANA → p53/pRb; vGPCR/VEGF; HIV Tat synergy). Forms: classic, endemic (children), iatrogenic, epidemic (AIDS — stage 4). Violaceous non-blanching patch → plaque → nodule; legs, nose tip, hard palate; lymphoedema. Visceral: GIT commonest (bleeding), lung most fatal. Histo: spindle cells + slit-like vessels + extravasated RBCs, LANA-1+. Dx biopsy. Rx: ART (50–80% regress), doxorubicin/paclitaxel for systemic, radiotherapy. Avoid steroids. KS-IRIS after ART.',
  src: 'IEYA study guide pp. 32–33; illness scripts (Kaposi sarcoma)', real: ['ks_skin|Kaposi sarcoma skin and palate lesions with histology'],
});

CASE({
  id: 'malaria', cat: ['BCMH'], covers: ['Malaria'], title: 'Malaria', dx: 'Plasmodium falciparum malaria',
  syn: ['malaria', 'falciparum', 'plasmodium'], dxKw: ['malaria|falciparum|plasmodium', 'travel|mozambique|limpopo|endemic', 'severe|complicated|uncomplicated'],
  dxWhy: 'Fever after travel to a malaria area (lowveld, Mozambique/Zimbabwe) = malaria until proven otherwise; P. falciparum ≈ 95% in southern Africa. Grade severity: impaired consciousness, hypoglycaemia, severe anaemia, jaundice, AKI, parasitaemia > 2–5%, vomiting, pregnancy → severe. Differentials: influenza, typhoid, tick-bite fever, meningitis, sepsis.',
  susp: 'Fever in someone returning from a malaria area → malaria (P. falciparum) until proven otherwise. Differentials: flu, typhoid, tick-bite fever, meningitis, sepsis, viral hepatitis.',
  suspKw: ['malaria', 'travel|mozambique|endemic|limpopo|mpumalanga', 'falciparum|plasmodium', 'typhoid|tick|meningitis|flu|sepsis'],
  gen: r => {
    const sev = r.chance(0.55), place = r.pick(['Mozambique (Inhambane)', 'Mozambique (Maputo)', 'Zimbabwe', 'the Kruger Park area', 'northern KZN']), age = r.int(17, 55), sex = r.sex(0.45);
    const delay = r.int(7, 16);
    return {
      sex, age, build: r.build(), setting: r.hosp(), job: r.pick(['student', 'truck driver', 'tour guide', 'accountant', 'miner']),
      brief: `Back from ${place} ${delay} days ago. ${r.int(2, 4)} days of fever, rigors, headache, vomiting.${sev ? ' Family says he/she has become drowsy.' : ''} No chemoprophylaxis.`,
      pc: sev ? '"I\'m so cold, then burning… my head… I can\'t keep anything down."' : '"I\'ve had fevers and shivering every day, and a bad headache. I thought it was flu."',
      v: sev ? {hr: r.int(118, 132), sbp: r.int(92, 104), dbp: r.int(54, 62), rr: r.int(24, 30), sat: r.int(93, 96), t: r.f(39.2, 40.4), gcs: r.int(10, 13)} : {hr: r.int(100, 112), sbp: 116, dbp: 72, rr: 18, sat: 98, t: r.f(38.6, 39.6), gcs: 15},
      signs: ['fever', 'sweaty'].concat(sev ? ['drowsy', 'jaundice'] : []),
      flags: {falciparum: true, severeMalaria: sev, cerebralMalaria: sev},
      lab: sev ? {Hb: [6.8, 9.2], Plt: [22, 48], Gluc: [1.9, 2.8], TBil: [48, 90], Cr: [140, 260], Urea: [12, 22], Lact: [4.2, 6.8], HCO3: [14, 18], LDH: [420, 760], Hapt: [0.05, 0.15]} : {Hb: [11.4, 13.2], Plt: [70, 120], TBil: [18, 30], LDH: [260, 340]},
      prof: [[`Returned from ${place} ${delay} days ago`, 1, 'Travel history is essential — SA endemic areas are Limpopo, Mpumalanga, northern KZN lowveld; most SA cases are imported from Mozambique/Zimbabwe.'], ['No malaria prophylaxis', 1, 'Non-immune traveller without chemoprophylaxis → high risk of severe disease.'], [`${age} years old`, 0, 'Children < 5, pregnant women, non-immune travellers and HIV+ patients are highest risk.'], [r.pick(['Travelled in December', 'Travelled in March']), 1, 'Peak transmission Sept–May (rainy season).'], ['Works in an office in Johannesburg', 0, 'Not relevant.']],
      hx: [
        ['Fever pattern', 'Shivering, then very hot, then I sweat — every day.', 1, 'Paroxysms from synchronous RBC rupture + TNF/IL-1 release.'],
        ['Travel', `I was in ${place} for ${r.int(5, 14)} days — we stayed near the water.`, 1],
        ['Mosquito bites / prophylaxis', 'Lots of mosquito bites. I didn\'t take any tablets — I didn\'t think I needed to.', 1],
        ['Headache / confusion', sev ? '(Family) {He}\'s been confused since this morning and very sleepy.' : 'Bad headache, but my head is clear.', sev ? 1 : 0, 'Impaired consciousness = severe/cerebral malaria.'],
        ['Urine', sev ? 'It\'s very dark, like Coke, and not much of it.' : 'Normal.', sev ? 1 : 0, 'Haemoglobinuria (blackwater) / AKI.'],
        ['Vomiting', 'I vomit everything, even water.', sev ? 1 : 0, 'Can\'t take oral treatment → treat as severe.'],
        ['Pregnancy', sex === 'F' ? 'No, I\'m not pregnant.' : '—', 0],
        ['HIV', 'Negative last year.', 0],
      ],
      ex: [['General (end of bed)', `${sev ? 'Drowsy, ' : ''}febrile, ${sev ? 'jaundiced and pale' : 'flushed'}.`, 1], ['Abdomen', 'Tender splenomegaly (2 cm), liver edge palpable.', 1], ['Neurological', sev ? 'GCS 12 (E3V4M5). No neck stiffness. No focal deficit.' : 'Alert, no meningism.', sev ? 1 : 0], ['Skin', 'No rash, no eschar.', 0]],
      res: {RDT: 'POSITIVE — HRP-2 (P. falciparum) band present.', MALSMEAR: {text: `Thick film: parasites seen. Thin film: P. falciparum ring forms, multiply-infected RBCs; parasitaemia ${sev ? r.int(6, 14) : r.f(0.4, 1.6)}%.`, img: 'malaria_film', cap: 'Thin smear: P. falciparum ring forms'}, GLUCO: sev ? 'Glucose 2.3 mmol/L — LOW.' : 'Glucose 5.6 mmol/L.', DIP: sev ? 'Blood 3+ (haemoglobinuria) · Protein 1+ · Urobilinogen +' : 'Urobilinogen +, otherwise negative.', BC: 'No growth.', LP: 'Opening pressure normal. CSF clear, WCC 1, protein 0.4, glucose 2.0 (serum 2.6). No meningitis.'},
    };
  },
  keyInv: ['RDT', 'MALSMEAR', 'PANEL_FBC', 'GLUCO'], okInv: ['PANEL_UE', 'PANEL_LFT', 'PANEL_LACT', 'PANEL_ABG', 'BC', 'DIP', 'PANEL_HAEMOL', 'PANEL_COAG', 'HIVR'],
  must: [{k: 'artesunate|act', n: 'Correct antimalarial (IV artesunate if severe; artemether-lumefantrine if uncomplicated)', why: 'Severe: IV artesunate ≥ 24 h (↓ mortality vs quinine) then full oral ACT. Uncomplicated: artemether–lumefantrine (Coartem) with fatty food for 3 days.'}],
  good: {artesunate: {m: 'IV artesunate started — parasite clearance begins within hours (endoperoxide bridge → free radicals).', fx: {v: {t: -0.6}}}, coartem: {m: 'Artemether-lumefantrine started (take with fatty food).'}, dextrose: {m: 'Hypoglycaemia corrected — GCS improving slightly.', fx: {v: {gcs: +1}, labSet: {Gluc: 6.1}}}},
  Q: [
    {s: 'micro', q: 'Describe the life cycle of Plasmodium and explain why some species relapse.', a: 'Female Anopheles injects sporozoites → liver (hepatocytes, schizonts) → merozoites released → invade RBCs (ring → trophozoite → schizont) → rupture (fever paroxysms) → some become gametocytes → taken up by the mosquito (sexual cycle in the mosquito = definitive host; humans intermediate). P. vivax and P. ovale form dormant liver hypnozoites → relapse months/years later → need primaquine.', kw: ['sporozoite', 'liver|hepatocyte', 'merozoite|rbc|red cell', 'gametocyte|mosquito', 'hypnozoite|vivax|ovale']},
    {s: 'mech', q: 'Why does P. falciparum cause severe disease such as cerebral malaria?', a: 'P. falciparum infects RBCs of all ages (high parasitaemia). PfEMP1 "knobs" → cytoadherence and sequestration in the microvasculature + rosetting → microvascular obstruction → cerebral malaria, AKI, ARDS, lactic acidosis, hypoglycaemia. RBC rupture → haemolysis (anaemia, jaundice, ↑LDH, ↓haptoglobin, splenomegaly) + TNF/IL-1 → fever. Thrombocytopenia is common; can trigger DIC; blackwater fever = massive intravascular haemolysis.', kw: ['all ages|parasitaemia', 'pfemp1|knob|cytoadher|sequest', 'microvascular|obstruct|rosett', 'haemoly|ldh|haptoglobin', 'tnf|il-1']},
    {s: 'comp', q: 'List the features that make malaria "severe".', a: 'Impaired consciousness/convulsions, prostration, respiratory distress/acidosis, hypoglycaemia, severe anaemia (Hb < 7), jaundice, AKI, haemoglobinuria, shock, bleeding/DIC, parasitaemia > 2–5%, vomiting (can\'t take oral), pregnancy, young children → admit and give IV artesunate.', kw: ['conscious|coma|cerebral|convuls', 'hypoglyc', 'anaemia|hb', 'jaundice|aki|kidney|haemoglobinuria', 'parasitaemia|vomit|acidosis|shock']},
    {s: 'inv', q: 'Which tests confirm malaria and what does each tell you? Interpret this patient\'s results.', a: 'Malaria RDT (HRP-2 antigen; stays + weeks after cure) and/or thick and thin smear: thick = detects (more sensitive), thin = species + % parasitaemia. Repeat if negative but suspicion high. FBC (↓ platelets, anaemia), glucose, U&E, lactate. Low glucose, high parasitaemia, raised bilirubin/creatinine and lactate indicate severe falciparum malaria. Malaria is a Category 1 notifiable condition (24 h).', kw: ['rdt|rapid', 'thick', 'thin|species|parasitaemia', 'platelet|glucose|lactate', 'notif']},
    {s: 'mgmt', q: 'Outline your management.', a: 'Severe: admit (high care), IV artesunate for at least 24 h then a full course of oral artemether–lumefantrine; correct hypoglycaemia; fluids carefully (ARDS risk); monitor glucose, Hb, renal function; transfuse if severe anaemia; dialysis for AKI. Uncomplicated: oral artemether–lumefantrine with fatty food, 3 days (+ single low-dose primaquine in low-transmission areas to kill gametocytes). Notify within 24 h (Category 1). Prevention: ABCD — Awareness, Bite prevention (nets, DEET, indoor residual spraying), Chemoprophylaxis, prompt Diagnosis.', kw: ['artesunate', 'artemether|lumefantrine|coartem|act', 'glucose|hypoglyc', 'notif', 'admit|monitor|fluid']},
    {s: 'pharm', q: 'How do artemisinins work, and why is primaquine used with caution?', a: 'Artemisinins act rapidly on blood stages via their endoperoxide bridge → free radicals; monotherapy is forbidden (resistance), hence ACT combinations. Primaquine kills hypnozoites (vivax/ovale) and gametocytes; it causes haemolysis in G6PD deficiency (check G6PD) and is avoided in pregnancy. Quinine (backup) causes cinchonism and hypoglycaemia. Chemoprophylaxis: doxycycline (photosensitivity), atovaquone-proguanil, mefloquine (neuropsychiatric).', kw: ['endoperoxide|free radical', 'monotherapy|resistance|combination', 'g6pd|haemoly', 'hypnozoite|gametocyte']},
  ],
  summary: 'Female Anopheles; P. falciparum ≈ 95% in southern Africa; endemic Limpopo/Mpumalanga/N-KZN, imports from Mozambique/Zimbabwe, peak Sept–May. Falciparum: all-age RBCs, PfEMP1 cytoadherence → sequestration → cerebral malaria, AKI, ARDS, acidosis, hypoglycaemia. Haemolysis (↑LDH, ↓hapto), ↓platelets. Dx: RDT (HRP-2) + thick (detect) / thin (species, %). Severe → IV artesunate ≥ 24 h then ACT; uncomplicated → artemether–lumefantrine with fat × 3 d (+ low-dose primaquine). Vivax/ovale hypnozoites → primaquine (G6PD). Cat 1 NMC (24 h). Prevention ABCD; vaccines RTS,S/R21.',
  src: 'IEYA study guide pp. 34–36; illness scripts (Malaria); BCMH cluster "Fever after a trip"', real: ['malaria_film|Thin smear: P. falciparum ring forms'],
});

CASE({
  id: 'candida', cat: ['BCMH'], covers: ['Oral candidiasis'], title: 'Oral thrush', dx: 'Oral (pseudomembranous) candidiasis',
  syn: ['candid', 'thrush'], dxKw: ['candid|thrush', 'hiv|inhaled steroid|ics|antibiotic|diabet', 'leukoplakia|hairy|differential'],
  dxWhy: 'White plaques that scrape off leaving a red, bleeding base = pseudomembranous candidiasis. Look for the reason defences failed: HIV (persistent oral = stage 3; oesophageal = stage 4), inhaled steroids without rinsing, broad-spectrum antibiotics, diabetes, dentures, extremes of age. Differentials: oral hairy leukoplakia (EBV, lateral tongue, does not scrape off), leukoplakia (pre-malignant), lichen planus.',
  susp: 'Oral candidiasis (thrush) — an opportunistic infection, so ask why: HIV, inhaled corticosteroids, recent antibiotics, diabetes, dentures. Differentials: oral hairy leukoplakia, leukoplakia, lichen planus.',
  suspKw: ['candid|thrush|fung', 'hiv|steroid|inhaler|antibiotic|diabet|denture', 'leukoplakia|lichen'],
  gen: r => {
    const cause = r.w({ics: 2, hiv: 3, abx: 1, denture: 1});
    const sex = r.sex(0.5), age = cause === 'denture' ? r.int(68, 84) : r.int(22, 58);
    const ody = cause === 'hiv' && r.chance(0.5);
    return {
      sex, age, build: r.build(), setting: r.pick(CLINICS), job: r.pick(['retired', 'cleaner', 'shop assistant', 'clerk', 'electrician']),
      brief: `White patches in the mouth for ${r.int(1, 4)} weeks${ody ? ', now painful swallowing' : ''}.`,
      pc: ody ? '"My mouth is white inside and now it hurts when I swallow food."' : '"There\'s white stuff on my tongue that won\'t go away, and my mouth burns."',
      v: {hr: 82, sbp: 122, dbp: 76, rr: 16, sat: 98, t: 36.9, gcs: 15},
      flags: cause === 'hiv' ? {hiv: true} : {asthma: cause === 'ics', diabetes: cause === 'denture' && r.chance(0.5)},
      meds: cause === 'ics' ? ['bud_form'] : [],
      lab: cause === 'hiv' ? {CD4: [90, 320], VL: [20000, 300000]} : cause === 'denture' ? {Gluc: [11, 17], HbA1c: [8.5, 11]} : {},
      prof: [[`${age} years old`, cause === 'denture' ? 1 : 0, 'Extremes of age (neonates, elderly denture wearers).'], [cause === 'ics' ? 'Asthmatic using a steroid inhaler' : cause === 'hiv' ? 'Never tested for HIV, recent weight loss' : cause === 'abx' ? 'Finished a long course of antibiotics last week' : 'Wears full dentures day and night', 1, 'This is why local/systemic defences failed.'], ['Non-smoker', 0, 'Smoking matters more for leukoplakia.'], ['Lives with family', 0, '—']],
      hx: [
        ['Mouth', 'White patches on my tongue and cheeks. When I scrape them off it bleeds a little.', 1, 'Scrapes off with a red base = pseudomembranous candidiasis (vs leukoplakia).'],
        ['Swallowing', ody ? 'It hurts going down my chest when I swallow.' : 'Swallowing is fine.', ody ? 1 : 0, 'Odynophagia = oesophageal candidiasis (WHO stage 4) — treat empirically.'],
        ['Inhaler use', cause === 'ics' ? 'I use the purple/red pump twice a day. I don\'t have a spacer and I don\'t rinse my mouth.' : 'No inhalers.', cause === 'ics' ? 1 : 0],
        ['Antibiotics', cause === 'abx' ? 'Two weeks of antibiotics for a chest infection.' : 'No antibiotics recently.', cause === 'abx' ? 1 : 0, 'Broad-spectrum antibiotics kill competing flora.'],
        ['HIV / weight', cause === 'hiv' ? 'I lost weight and I\'ve had diarrhoea on and off. I\'ve never tested.' : 'Tested negative last year.', cause === 'hiv' ? 1 : 0],
        ['Dentures / sugar', cause === 'denture' ? 'I sleep with my dentures in. The clinic said my sugar is high.' : 'No dentures.', cause === 'denture' ? 1 : 0],
      ],
      ex: [['Head & neck', `Creamy white plaques on tongue, buccal mucosa and palate; scraping leaves an erythematous bleeding base.${cause === 'denture' ? ' Erythema under the upper denture; angular cheilitis.' : ''}`, 1], ['General (end of bed)', cause === 'hiv' ? 'Thin. Generalised lymphadenopathy.' : 'Well.', cause === 'hiv' ? 1 : 0]],
      res: {HIVR: cause === 'hiv' ? 'Reactive. Confirmatory test reactive.' : 'Non-reactive.', GLUCO: cause === 'denture' ? 'Glucose 14.2 mmol/L — HIGH.' : 'Glucose 5.4 mmol/L.', BX: 'Scraping (KOH/Gram): Gram-positive budding yeasts with pseudohyphae. Culture on Sabouraud agar: creamy colonies; germ-tube positive → Candida albicans.'},
    };
  },
  keyInv: ['HIVR'], okInv: ['BX', 'GLUCO', 'PANEL_CD4', 'PANEL_GLUC', 'PANEL_FBC'],
  must: [{k: 'antifungal_topical|azole', n: 'Antifungal (nystatin/miconazole for mild oral; fluconazole if moderate–severe or oesophageal)', why: 'Polyenes bind ergosterol → pores; azoles inhibit 14α-demethylase → ↓ ergosterol.'}],
  good: {nystatin: {m: 'Topical nystatin for mild oral thrush.'}, fluco: {m: 'Fluconazole — needed for moderate–severe or oesophageal disease.'}},
  Q: [
    {s: 'micro', q: 'Describe the organism and how it is identified in the lab.', a: 'Candida albicans: dimorphic yeast — oval budding yeasts + pseudohyphae (invasive form); Gram-positive on Gram stain; germ-tube test positive (C. albicans); grows on Sabouraud agar (white-cream colonies). Normal flora of mouth, GIT, vagina, skin; most infections endogenous. Non-albicans: C. glabrata, C. krusei (fluconazole-resistant), C. auris (MDR, outbreaks).', kw: ['yeast', 'pseudohyph', 'germ tube|germ-tube', 'sabouraud', 'commensal|normal flora|endogenous']},
    {s: 'cause', q: 'Why did this patient develop thrush? List the risk factors and explain each.', a: 'Risk factors = why defences fail: HIV (↓CD4/TH17), inhaled corticosteroids without rinsing (local immunosuppression), broad-spectrum antibiotics (kill competing flora), diabetes, dentures, xerostomia, chemotherapy/neutropenia, extremes of age (neonates), poor hygiene. In an adult without an obvious cause → think HIV.', kw: ['hiv|cd4', 'steroid|inhaler|ics', 'antibiotic|flora', 'diabet|denture|age|neutrop']},
    {s: 'path', q: 'What are the clinical forms of oral candidiasis, and how do you tell it apart from oral hairy leukoplakia?', a: 'Pseudomembranous (thrush — white plaques that scrape off leaving a red bleeding base), erythematous/atrophic (red, under dentures, after antibiotics), angular cheilitis, hyperplastic (leukoplakia-like, doesn\'t scrape off). Oral hairy leukoplakia (EBV) is on the lateral tongue and does NOT scrape off; leukoplakia is pre-malignant. Persistent oral candida = WHO stage 3; oesophageal candidiasis = WHO stage 4 (AIDS-defining).', kw: ['pseudomembran|scrape', 'erythematous|atrophic|angular', 'hairy leukoplakia|ebv|lateral', 'stage 3|stage 4|oesophag']},
    {s: 'mgmt', q: 'How would you manage this patient?', a: 'Treat and remove the cause: mild oral — topical nystatin suspension or miconazole gel; moderate–severe or odynophagia (oesophageal) — oral fluconazole; failure → endoscopy (CMV/HSV ulcers). Test for HIV (with counselling). Prevention: rinse mouth/use a spacer after ICS, denture hygiene (remove at night), control glucose; fluconazole prophylaxis in neutropenia.', kw: ['nystatin|miconazole', 'fluconazole', 'hiv test|test for hiv|hiv', 'rinse|spacer|denture|glucose']},
    {s: 'pharm', q: 'Compare how nystatin and fluconazole work. What interaction matters with azoles?', a: 'Nystatin (polyene) binds ergosterol in the fungal membrane → pores → leakage. Fluconazole (azole) inhibits lanosterol 14α-demethylase (CYP51) → ↓ ergosterol synthesis. Azoles inhibit human CYP450 → interactions (warfarin ↑INR, statins). Echinocandins (caspofungin — glucan synthase) for invasive/resistant; amphotericin B (nephrotoxic, ↓K⁺/Mg²⁺) for severe systemic.', kw: ['ergosterol', 'pore|membrane|polyene', '14|demethylase|cyp51|lanosterol', 'cyp450|warfarin|interaction']},
  ],
  summary: 'C. albicans commensal yeast; disease when defences fail: HIV, ICS (rinse!), antibiotics, DM, dentures, neonates, chemo. Forms: pseudomembranous (scrapes off, red base), erythematous, angular cheilitis, hyperplastic. Persistent oral = stage 3; oesophageal (odynophagia) = stage 4. Dx clinical; KOH/Gram: budding yeast + pseudohyphae; germ tube +; Sabouraud. Ddx: oral hairy leukoplakia (EBV, lateral tongue, no scrape), leukoplakia. Rx: nystatin/miconazole (mild), fluconazole (moderate/oesophageal); azoles inhibit CYP450.',
  src: 'IEYA study guide pp. 37–38; illness scripts (Candidiasis)', real: ['oral_candida|Oral thrush and cutaneous candidiasis', 'candida_culture|Candida colonies on agar'],
});
